import { probeSchema } from "@octo/run-host";
import type { Capabilities } from "@octo/editor";
import StandaloneEditor from "./components/StandaloneEditor";
import { projectId } from "./api/fs/store";

/**
 * `/` opens the project — every config file in the folder this app serves — at its
 * first file that holds a flow; `/?file=<name>` opens it at that file.
 *
 * The capability schema is generated by the `octo` binary, cached on first probe, and
 * injected into the client editor; with no runner configured it resolves to null and
 * the editor falls back to its bundled JSON.
 */
export default async function Home({
  searchParams,
}: {
  searchParams: Promise<{ file?: string }>;
}) {
  const { file } = await searchParams;
  const capabilities = (await probeSchema()) as Capabilities | null;
  return <StandaloneEditor projectId={projectId()} file={file} capabilities={capabilities} />;
}
